import{c as e,Q as r,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"R12 強化提案 — unverified_success 閘門狀態 + 失敗歸因分層","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-05-r12-unverified-success-proposal.md","filePath":"research/reports/archive/2026-06-05-r12-unverified-success-proposal.md","lastUpdated":1780842316000}'),a={name:"research/reports/archive/2026-06-05-r12-unverified-success-proposal.md"};function n(d,t,i,c,l,u){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="r12-強化提案-—-unverified-success-閘門狀態-失敗歸因分層" tabindex="-1">R12 強化提案 — unverified_success 閘門狀態 + 失敗歸因分層 <a class="header-anchor" href="#r12-強化提案-—-unverified-success-閘門狀態-失敗歸因分層" aria-label="Permalink to &quot;R12 強化提案 — unverified_success 閘門狀態 + 失敗歸因分層&quot;">​</a></h1><blockquote><p><strong>來源</strong>：<code>research/reports/2026-05-17-harness-engineering.md</code> §「2026-06-05 深度更新」5 補充主題的「對 cc-workspace 的意義」。 <strong>接地</strong>：5 標籤分類 / H0–H3 ladder / 8 trace types 經主對話親自 grep <code>research/papers/2026-05-13-ai-harness-engineering-runtime-substrate-2605-13357.md</code>（行 46–73）原文確認。 <strong>狀態</strong>：APPLY 完成（commit b5715db8）。Landing 經 AskUserQuestion 核准（R12.1 進條文 + R12.2/3 進 GOTCHA）。 <strong>Falsifiable Prediction（prompt-lifecycle 慣例）</strong>：R12.1 添加<strong>不削弱 R1–R11 compliance</strong>——eval 條件 = ① healthcheck FAIL=0（實測 110/0/3 ✅）② auto-load byte ≤ 19,000（實測 18,993，餘 7 ✅）③ 既有 §R1–§R11 anchor 不變（measure.sh --gate PASS ✅）。回歸 ≥5pp → <code>git revert</code>（R11 / autoload-evolution 閉環）。 <strong>接地審計（R12.1 dogfood）</strong>：5 標籤 / H0–H3（Runtime Substrate <code>2605.13357</code> 行 46–73）+ Categorical 8B 全 0（<code>2605.12239</code> 行 92–93）+ Vesper 16.6%/0%（<code>2605.15221</code> 行 107–110）<strong>全經主對話親自 grep</strong>，非報告轉述。</p></blockquote><hr><h2 id="_0-動機-—-本提案自身的-unverified-success-範例" tabindex="-1">0. 動機 — 本提案自身的 unverified_success 範例 <a class="header-anchor" href="#_0-動機-—-本提案自身的-unverified-success-範例" aria-label="Permalink to &quot;0. 動機 — 本提案自身的 unverified_success 範例&quot;">​</a></h2><p>來源報告審計表（行 1156）標 Runtime Substrate「✅ 原文命中」，且本次更新聲明「每數字親 grep」（行 1091）——<strong>卻 ship 了一個錯誤 cross-ref</strong>：報告行 1117 引用「MEMORY Lesson 2026-06-05-B」指稱「subagent 報 clean 但實際殘留問題」，但 MEMORY 實際的 2026-06-05-B 是「provenance header 過度宣稱」。真正命中 <code>unverified_success</code> 的是：</p><ul><li><strong>Lesson 2026-06-05-A</strong>：sub-agent 自稱「親驗」的數字直接寫進產物 → advisor 攔截 3 處誤植（ACE −82.6% / TTFT 13–31% / MetaGPT −40%）。</li><li><strong>Lesson 2026-06-04-G</strong>：memory-compactor 自報「32 保留」實際流失 12 個 Lesson。</li><li><strong>Lesson 2026-06-05-D</strong>：同一 adjudicate.sh 主對話跑 6/6、經 sub-agent 中介 4/6（block-dangerous hook 污染）。</li></ul><p>「聲明已驗證 + 審計表打勾 + 實際 ship 錯誤」= 教科書級 <code>unverified_success</code>：correct-looking behavior without proper evidence structure。這正是本提案要防的失敗模式。</p><hr><h2 id="_1-核心概念-runtime-substrate-2605-13357-親-grep-接地" tabindex="-1">1. 核心概念（Runtime Substrate 2605.13357，親 grep 接地） <a class="header-anchor" href="#_1-核心概念-runtime-substrate-2605-13357-親-grep-接地" aria-label="Permalink to &quot;1. 核心概念（Runtime Substrate 2605.13357，親 grep 接地）&quot;">​</a></h2><h3 id="_5-標籤結果分類-原文行-69–73-報告只列了-3-個" tabindex="-1">5 標籤結果分類（原文行 69–73，報告只列了 3 個） <a class="header-anchor" href="#_5-標籤結果分類-原文行-69–73-報告只列了-3-個" aria-label="Permalink to &quot;5 標籤結果分類（原文行 69–73，報告只列了 3 個）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>標籤</th><th>定義</th><th>對應 cc-workspace</th></tr></thead><tbody><tr><td><code>autonomous_verified_success</code></td><td>需求達成 + 充分證據 + 無缺 harness 介入</td><td>主對話親自跑驗證 + 展示輸出（R4/R12 達標態）</td></tr><tr><td><code>assisted_verified_success</code></td><td>patch 正確但需人工協助</td><td>advisor / 使用者 gate 後達成</td></tr><tr><td><strong><code>unverified_success</code></strong></td><td>行為看似正確但<strong>缺證據結構</strong></td><td><strong>本 workspace 反覆失敗模式</strong>（A/D/G）</td></tr><tr><td><code>failed</code></td><td>行為或測試失敗</td><td>R12 Fail Loud 已涵蓋</td></tr><tr><td><code>unsafe_invalid</code></td><td>測試被削弱 / 出現無關編輯</td><td>命中 R3 外科刀 + compactor over-prune（G）</td></tr></tbody></table><h3 id="h0–h3-成熟度梯度-原文行-58–61" tabindex="-1">H0–H3 成熟度梯度（原文行 58–61） <a class="header-anchor" href="#h0–h3-成熟度梯度-原文行-58–61" aria-label="Permalink to &quot;H0–H3 成熟度梯度（原文行 58–61）&quot;">​</a></h3><ul><li>H0 task + repo｜H1 +tool/test registry｜H2 +memory/task-state｜<strong>H3 +deterministic checks / failure attribution / verification protocols</strong></li><li>四層<strong>全能產出能跑的 patch</strong>，但只有 H3 有可審計證據包。「通過測試」≠「有可審計的可靠性」。</li><li>cc-workspace 現況 ≈ H2–H3 之間（K×M 稽核到位，Entropy Auditor 缺）。</li></ul><h3 id="失敗歸因分層-life-harness-2605-22166-4-類-runtime-substrate-attribution-log" tabindex="-1">失敗歸因分層（Life-Harness 2605.22166 4 類 + Runtime Substrate attribution log） <a class="header-anchor" href="#失敗歸因分層-life-harness-2605-22166-4-類-runtime-substrate-attribution-log" aria-label="Permalink to &quot;失敗歸因分層（Life-Harness 2605.22166 4 類 + Runtime Substrate attribution log）&quot;">​</a></h3><p>報告引入 Life-Harness 4 generic layers，但 advisor 指示<strong>改用本 workspace 實際反覆失敗</strong>而非進口標籤：</p><table tabindex="0"><thead><tr><th>歸因層</th><th>本 workspace 實例</th><th>已知防範</th></tr></thead><tbody><tr><td><strong>Verdict 層</strong></td><td>subagent/workflow 自報 verdict 非證據</td><td>subagent-strategy.md:67（已存在）</td></tr><tr><td><strong>Execution-env 層</strong></td><td>確定性 gate 經 sub-agent 中介被污染</td><td>Lesson 2026-06-05-D（adjudicate 絕不經 sub-agent）</td></tr><tr><td><strong>Provenance 層</strong></td><td>數字 grep 存在 ≠ 對應正確；header 過度宣稱</td><td>Lesson 2026-06-04-G / 2026-06-05-A/B</td></tr><tr><td><strong>Entropy 層</strong></td><td>孤兒研究檔 / 殘留 worktree / stale cross-ref</td><td>Lesson 2026-06-04-E（無常態檢查）</td></tr></tbody></table><hr><h2 id="_2-強化提案-行為-delta-非重述既有" tabindex="-1">2. 強化提案（行為 delta，非重述既有） <a class="header-anchor" href="#_2-強化提案-行為-delta-非重述既有" aria-label="Permalink to &quot;2. 強化提案（行為 delta，非重述既有）&quot;">​</a></h2><blockquote><p>自檢通過：以下每條都防一個 R12 + subagent-strategy.md:67 <strong>尚未防</strong>的失敗。</p></blockquote><h3 id="_2-1-r12-1-—-unverified-success-閘門狀態-核心" tabindex="-1">2.1 R12.1 — unverified_success 閘門狀態（核心） <a class="header-anchor" href="#_2-1-r12-1-—-unverified-success-閘門狀態-核心" aria-label="Permalink to &quot;2.1 R12.1 — unverified_success 閘門狀態（核心）&quot;">​</a></h3><blockquote><p>subagent / workflow 回報的「成功」一律記為 <strong><code>unverified_success</code></strong> 中間態，<strong>直到主對話親自跑確定性檢查</strong>（grep / test / healthcheck）才可升為 verified。<code>unverified_success</code> <strong>不得</strong>作為「完成」回報給使用者。確定性 gate（adjudicate / done-check）<strong>絕不經 sub-agent 中介</strong>（Lesson 2026-06-05-D）。</p></blockquote><ul><li><strong>行為 delta</strong>：subagent-strategy.md:67 說「verdict 非證據，採信前必 grep」；本條給這個中間態一個<strong>名字 + 閘門語義</strong>——明確「未驗證前不可宣告完成」，並把 Lesson 2026-06-05-D 的「gate 不經 sub-agent」從 MEMORY 提升為 R12 條文。</li></ul><h3 id="_2-2-r12-2-—-失敗歸因到層" tabindex="-1">2.2 R12.2 — 失敗歸因到層 <a class="header-anchor" href="#_2-2-r12-2-—-失敗歸因到層" aria-label="Permalink to &quot;2.2 R12.2 — 失敗歸因到層&quot;">​</a></h3><blockquote><p>驗證失敗時，YOU MUST 將失敗歸因到一層（Verdict / Execution-env / Provenance / Entropy），不接受「隨機修補」。歸因 = 後續修復方向的前提（Runtime Substrate：observation ≠ diagnosis）。</p></blockquote><ul><li><strong>行為 delta</strong>：現 R12 只要求「Fail Loud」（失敗要明示），未要求<strong>結構化歸因</strong>。隨機修補是本 workspace 多次 debug 繞圈的根因。</li></ul><h3 id="_2-3-r12-3-—-entropy-自檢-h3-補完" tabindex="-1">2.3 R12.3 — Entropy 自檢（H3 補完） <a class="header-anchor" href="#_2-3-r12-3-—-entropy-自檢-h3-補完" aria-label="Permalink to &quot;2.3 R12.3 — Entropy 自檢（H3 補完）&quot;">​</a></h3><blockquote><p>宣告「完成」前的 PGE 除 healthcheck 外，加一道 entropy 自檢：① 本次產生的研究/報告檔已有入口引用（無孤兒，Lesson E）；② 無殘留 worktree（<code>git worktree list</code>）；③ 無 stale cross-ref / 被削弱測試（<code>unsafe_invalid</code> 防線）。</p></blockquote><ul><li><strong>行為 delta</strong>：把 Lesson 2026-06-04-E 的事後補救升為<strong>常態 PGE 檢查項</strong>，對應 Runtime Substrate Entropy Auditor。</li></ul><hr><h2 id="_3-landing-選項-須使用者決策-—-auto-load-修改-blocks" tabindex="-1">3. Landing 選項（須使用者決策 — auto-load 修改 blocks） <a class="header-anchor" href="#_3-landing-選項-須使用者決策-—-auto-load-修改-blocks" aria-label="Permalink to &quot;3. Landing 選項（須使用者決策 — auto-load 修改 blocks）&quot;">​</a></h2><p>byte 預算：auto-load 現 <strong>18,455 / 19,000，餘 545 B</strong>。</p><ul><li><strong>R12.1 條文</strong>（≈ 350–400 B）放 core.md §R12 → 餘裕剩 ~150 B，逼近上限。</li><li><strong>R12.2 / R12.3</strong> 全文放 GOTCHA（零 byte 成本）+ R12 一行指針（≈ 80 B/條）。</li></ul><p>三種 landing 形狀見 AskUserQuestion。所有 auto-load 修改走 <code>/autoload-evolution</code>（≤1 規則/cycle、≤50 行 diff、eval 回歸 ≥5pp 則 revert）—— R11 convention-first。</p><hr><h2 id="_4-其餘-3-主題處置-章節完整性" tabindex="-1">4. 其餘 3 主題處置（章節完整性） <a class="header-anchor" href="#_4-其餘-3-主題處置-章節完整性" aria-label="Permalink to &quot;4. 其餘 3 主題處置（章節完整性）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主題</th><th>「對 cc-workspace 的意義」</th><th>處置</th></tr></thead><tbody><tr><td>1 自動優化三世代</td><td>「摘要丟失改進信號」與 workspace 同源</td><td><strong>無新動作</strong>——已由 subagent-strategy.md:67 + autoload-evolution 覆蓋；GOTCHA 補一句「trace 不壓縮」</td></tr><tr><td>3 能力下限 + 弔詭</td><td>Capability Floor 升級為論文背書；升 Opus 須同步加強驗證</td><td><strong>GOTCHA 補論文引用</strong>（Categorical 8B 全 0 / Vesper 16.6% hack）+ 認知註記；不動 auto-load</td></tr><tr><td>4 可遷移性</td><td>12-Rule = 可跨模型遷移 artifact</td><td><strong>無新動作</strong>——認知確認（MEMORY R1-R12 存活已記）</td></tr></tbody></table><blockquote><p>守 R2：主題 1/4 已被現有條文覆蓋，<strong>不為湊「全部處理」而新增冗餘規則</strong>。主題 3 僅補 GOTCHA 背書，不佔 auto-load byte。</p></blockquote>',37)])])}const p=e(a,[["render",n]]);export{h as __pageData,p as default};
